package com.northstarbank.core;
import java.math.BigDecimal;import java.time.LocalDate;import java.util.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;
@Configuration class CoreSeeder{@Bean CommandLineRunner seedCore(CustomerRepo cs,AccountRepo as,TransactionRepo ts,CardRepo cards){return args->{if(cs.count()>0)return;String[] names={"Alex Morgan","Jamie Patel","Sam Taylor","Jordan Lee","Priya Shah","Oliver Smith","Amelia Jones","Noah Williams","Isla Brown","Leo Wilson"};for(int i=1;i<=40;i++){String id=String.format("C%04d",i),branch=String.format("B%02d",(i-1)%9+1);String name=(i==1||i==10)?"Alex Morgan":(i==2||i==11)?"Jamie Patel":names[i%names.length]+" "+i;cs.save(new CoreCustomer(id,name,"07700 "+String.format("%06d",i),"customer"+i+"@example.test",branch,i==3||i==17||i==29));int accountCount=i<=20?2:1;for(int a=0;a<accountCount;a++){String an="100200"+String.format("%04d",i)+a;as.save(new CoreAccount(an,id,a==0?"Everyday Current":"Easy Saver",new BigDecimal(1250+i*17+a*300)));for(int t=0;t<8;t++)ts.save(new CoreTransaction(an,LocalDate.now().minusDays(t*3L),new BigDecimal((t%3==0?"-":"")+(10+i+t)+".25"),t%2==0?"Grocery purchase":"Transfer received",t));if(a==0&&i<=30)cards.save(new CoreCard("CARD"+String.format("%03d",i),an,id,"•••• •••• •••• "+String.format("%04d",1000+i),i%10==0?"permanently_blocked":i%8==0?"temporarily_blocked":i%7==0?"replaced":"active"));}}};}}
